/**
 * Offline support for the built app (M8). The service worker (generated by the `pwa` plugin in
 * vite.config.ts) caches only the app itself; the game's files are read from the user's folder
 * and never reach the network or the cache.
 */
export function registerServiceWorker() {
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return;
  addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js').catch((e) => console.warn('Service worker:', e));
  });
}
